import ast as _ast
import numpy as np
import pandas as pd

def walk(n, seed):
    """n seeded daily closes: a random walk from 100."""
    rng = np.random.default_rng(seed)
    return [float(x) for x in 100 * np.exp(np.cumsum(0.012 * rng.standard_normal(n)))]

HAND = [10.0, 11.0, 12.0, 11.0, 10.0, 9.0, 10.0, 11.0, 13.0, 12.0]
_TIES = [10.0, 12.0, 11.0, 12.0, 13.0, 12.0, 11.0, 10.0, 11.0]

def _targets(close, n):
    tg = []
    for t, c in enumerate(close):
        prev = tg[-1] if tg else 0
        if t < n:
            tg.append(0)
            continue
        hi, lo = max(close[t - n:t]), min(close[t - n:t])
        tg.append(1 if c > hi else (-1 if c < lo else prev))
    return tg

def _ref(close, n):
    # reference: the target set at t - 1 earns bar t's return
    tg = _targets(close, n)
    return [0.0] + [tg[t - 1] * (close[t] / close[t - 1] - 1) for t in range(1, len(close))]

def _same_bar(close, n):
    # peeks: bar t's own target earns bar t's return
    tg = _targets(close, n)
    return [0.0] + [tg[t] * (close[t] / close[t - 1] - 1) for t in range(1, len(close))]

def _drop_last(close, n):
    return _ref(close, n)[:-1]

def _nudged(close, n):
    return [x + 1e-12 for x in _ref(close, n)]

def _close(a, b):
    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)
    return a.shape == b.shape and bool(np.allclose(a, b, rtol=0, atol=1e-9))

def _causal(fn, close, n):
    full = list(fn(close, n))
    return all(_close(fn(close[:k], n), full[:k]) for k in range(1, len(close) + 1))

def _no_loop(name="breakout_vector"):
    tree = _ast.parse(__learner_source__)
    funcs = {f.name: f for f in tree.body if isinstance(f, _ast.FunctionDef)}
    kinds = (_ast.For, _ast.While, _ast.ListComp, _ast.SetComp, _ast.DictComp, _ast.GeneratorExp)
    def loops(f):
        return any(isinstance(x, kinds) or (isinstance(x, _ast.Attribute)
                   and x.attr in ("apply", "map", "iterrows", "itertuples")) for x in _ast.walk(f))
    if name not in funcs or loops(funcs[name]):
        return False
    used = {x.id for x in _ast.walk(funcs[name]) if isinstance(x, _ast.Name)}
    return not any(loops(g) for k, g in funcs.items() if k in used and k != name)

