import numpy as np
import pandas as pd


def breakout_loop(close, n):
    """Strategy return at each bar, from an event loop."""
    out, target = [], 0
    for t in range(len(close)):
        seen = close[: t + 1]                 # all the loop may read at bar t
        ret = seen[t] / seen[t - 1] - 1 if t > 0 else 0.0
        out.append(target * ret)              # the target set at t - 1 earns it
        if t >= n:
            window = seen[t - n : t]          # the n closes before this one
            if seen[t] > max(window):
                target = 1
            elif seen[t] < min(window):
                target = -1                   # inside the channel: keep it
    return out


def breakout_vector(close, n):
    """The same returns with pandas or NumPy, no Python loop."""
    c = pd.Series(close, dtype=float)
    hi = c.rolling(n).max().shift(1)          # the n closes before bar t
    lo = c.rolling(n).min().shift(1)
    step = np.where(c > hi, 1.0, np.where(c < lo, -1.0, np.nan))
    target = pd.Series(step).ffill().fillna(0.0)
    ret = c.pct_change().fillna(0.0)
    return (target.shift(1).fillna(0.0) * ret).tolist()


def agree(loop_fn, vector_fn, close, n):
    """True when the two functions give the same returns at every bar."""
    a = np.asarray(loop_fn(close, n), dtype=float)
    b = np.asarray(vector_fn(close, n), dtype=float)
    return a.shape == b.shape and bool(np.allclose(a, b, rtol=0, atol=1e-9))
